examples.bad:
// Only static methods: move them to the top level.
class DateUtils {
  static DateTime mostRecent(List<DateTime> dates) =>
      dates.reduce((a, b) => a.isAfter(b) ? a : b);
}

// Static non-const fields count as instance-free state.
class _Favorites {
  static int mostFavorite = 0;
}

// A static getter induces a non-const field.
class Config {
  static String get name => 'config';
}

// A default constructor does not make the class a real type.
class Helpers {
  Helpers();
  static void run() {}
  static const int retries = 3;
}

// `extends Object` adds no members.
abstract class Registry extends Object {
  static final List<String> names = [];
  static void register(String name) => names.add(name);
}

// Static setter plus static method.
class Counter {
  static int _count = 0;
  static set count(int value) => _count = value;
  static void reset() => _count = 0;
}

// Unlike members inherited from a class, mixin members do not exempt this lint.
mixin Greets {
  void greet() {}
}
class Greeter with Greets {
  static void helper() {}
}

// Empty and static-only parents do not contribute instance members.
class EmptyParent {}

class ExtendsEmpty extends EmptyParent {
  static int value = 1;
}

class ImplementsEmpty implements EmptyParent {
  static int value = 1;
}

class StaticParent {
  static int value = 1;
}

class ExtendsStatic extends StaticParent {
  static void helper() {}
}

mixin class StaticMixinClass {
  static int value = 1;
}

// Only the merged interface's owners count, not overridden class declarations.
class MethodParent {
  void run() {}
}
mixin ReplacesMethod on MethodParent {
  void run() {}
}
class ReplacedMethod extends MethodParent with ReplacesMethod {
  static void helper() {}
}

class AccessorParent {
  int get value => 0;
  set value(int value) {}
}
mixin ReplacesAccessors {
  int get value => 1;
  set value(int value) {}
}
class ReplacedAccessors extends AccessorParent with ReplacesAccessors {
  static void helper() {}
}

examples.good:
// A group of constants is allowed.
class Color {
  static const red = '#f00';
  static const green = '#0f0';
  static const blue = '#00f';
}

// Instance members make it a real class.
class Point {
  final int x;
  Point(this.x);
  static Point origin() => Point(0);
}

// Sealed classes are exempt.
sealed class Shape {
  static Shape? parse(String text) => null;
}

// A named constructor is not a default constructor.
class Logger {
  Logger.named();
  static void log(String message) {}
}

// A supertype other than Object may contribute instance members.
class Base {
  void run() {}
}

class Derived extends Base {
  static void helper() {}
}


class Impl implements Base {
  @override
  void run() {}
  static void helper() {}
}

// An empty class has no members at all.
class Marker {}

// Top-level functions instead of a static-only class.
DateTime mostRecent(List<DateTime> dates) => dates.first;

// A mixin class's instance members also provide a real interface.
mixin class InstanceMixinClass {
  void run() {}
}

class InheritsMixinClass extends InstanceMixinClass {
  static void helper() {}
}

// One surviving class-owned member still exempts the class.
class TwoMethods {
  void first() {}
  void second() {}
}
mixin ReplacesFirst {
  void first() {}
}
class PartiallyReplaced extends TwoMethods with ReplacesFirst {
  static void helper() {}
}

// Getter and setter ownership must remain separate.
class AccessorParent {
  int get value => 0;
  set value(int value) {}
}
mixin ReplacesGetter {
  int get value => 1;
}
class RetainsSetter extends AccessorParent with ReplacesGetter {
  static void helper() {}
}

