// Each conditional nested inside another conditional is flagged (the inner
// conditional, matching dart_code_linter's nesting-level reporting).

void doubleNesting() {
  final x = a ? (b ? c : d) : e;
  final y = condition ? (isValid ? "yes" : "no") : "default";
  final z = (first ? (second ? 1 : 2) : 3) + 4;
}

// Triple nesting flags both inner conditionals (nesting levels 2 and 3).
String getStatus() {
  return active ? (verified ? (premium ? "premium" : "standard") : "unverified") : "inactive";
}

class StatusHelper {
  String describe(bool a, bool b, bool c) {
    return a ? (b ? (c ? "all" : "a,b") : "a") : "none";
  }
}

int calculate(bool x, bool y) {
  return x ? (y ? (100) : (50)) : (0);
}

List<String> getItems(bool filter) {
  return filter ? (items.isNotEmpty ? (items.toList()) : []) : items;
}

// Regression: the violation must still be found inside Dart 3 containers
// (pattern declaration, labeled statement, switch expression and subject,
// collection if/spread, record field).
void containersRegression(int rcount) {
  final (ra, _) = ((rcount > 0 ? (rcount > 1 ? 1 : 2) : 3), 0);
  lbl: {
    final rb = (rcount > 0 ? (rcount > 1 ? 1 : 2) : 3);
    print(rb);
  }
  final rc = switch (rcount) {
    0 => (rcount > 0 ? (rcount > 1 ? 1 : 2) : 3),
    _ => null,
  };
  final rd = switch ((rcount > 0 ? (rcount > 1 ? 1 : 2) : 3)) {
    _ => 0,
  };
  final re = [if (rcount > 0) (rcount > 0 ? (rcount > 1 ? 1 : 2) : 3)];
  final rf = [...[(rcount > 0 ? (rcount > 1 ? 1 : 2) : 3)]];
  final rg = (p: (rcount > 0 ? (rcount > 1 ? 1 : 2) : 3), q: 0);
  print([ra, rc, rd, re, rf, rg]);
}

