class Field {
  final int value;
  Field(this.value);

  @override
  bool operator ==(Object other) {
    if (other is! Field) return false;
    return value == other.value;
  }

  @override
  int get hashCode => value.hashCode;
}

class Pair {
  final int a;
  Pair(this.a);

  @override
  bool operator ==(Object other) => other is Pair && other.a == a;

  @override
  int get hashCode => a;
