// Pattern-based type test.
class Point {
  final int x;
  Point(this.x);

  @override
  bool operator ==(Object other) => switch (other) {
        Point(:final x) => x == this.x,
        _ => false,
      };

  @override
  int get hashCode => x;
}

// Casting something other than the parameter.
class Holder {
  final Object inner;
  Holder(this.inner);

  @override
  bool operator ==(Object other) =>
      other is Holder && (inner as num) == (other.inner as num);

  @override
  int get hashCode => inner.hashCode;
}

// Casts in ordinary methods are not reported.
class Util {
  bool equals(Object other) => (other as Util) == this;
}

docs:
Flags `throw` inside a `finally` block.

Throwing from a finally replaces whatever the try or catch was doing: an
exception that was still propagating is silently discarded and a value the
try was about to return is lost. Keep finally blocks limited to cleanup. A
throw inside a closure or local function defined in the finally is left
alone, as is a throw whose innermost enclosing `try` is nested inside the
finally (in its body or catch clauses).

```dart
try {
  work();
} finally {
  throw StateError('cleanup failed'); // flagged
}
```

examples.bad:
class Ex implements Exception {}

void doThing() {}

void direct() {
  try {
    doThing();
  } finally {
    throw Ex();
  }
}

void afterCatch() {
  try {
    doThing();
  } catch (e) {
    print(e);
  } finally {
    throw Ex();
  }
}

void conditional(bool c) {
  try {
    doThing();
  } finally {
    if (c) {
      throw StateError('bad');
    }
  }
}

void asExpression(int? value) {
  try {
    doThing();
  } finally {
    final v = value ?? (throw ArgumentError());
    print(v);
  }
}

void inLoop(List<int> values) {
  try {
    doThing();
  } finally {
    for (final value in values) {
