}

void handleDynamic(dynamic value) {
  if (value is double) {
    print('double');
  } else if (value is int) {
    print('int');
  } else {
    print('other');
  }
}

void handleLocal(Object input) {
  final number = input;
  if (number is double) {
    print('double');
  } else if (number is int) {
    print('int');
  }
}

void handleOptional([Object? x]) {
  if (x is double) print('double'); else if (x is int) print('int');
}

void handleNamed({required num x}) {
  if (x is double) {
    print('double');
  } else if (x is int) {
    print('int');
  }
}

final closure = (num x) {
  if (x is double) {
    return 1;
  } else if (x is int) {
    return 2;
  }
  return 0;
};

void negated(num x) {
  if (x is! double) {
    print('not double');
  } else if (x is int) {
    print('int');
  }
}

