docs:
Flags field initializers in classes with a `const` constructor.

In a class that can be instantiated as a constant, a `final` instance field
initialized to a fixed value — either at its declaration or in the
initializer list of the class's only `const` constructor without using any
constructor parameter — stores the same value in every instance. A getter
expresses that without spending a field per object.

```dart
class A {
  final a = const [];         // flagged
  const A();
}

class B {
  final b;
  const B() : b = const [];   // flagged
}

class C {
  List get c => const [];     // preferred
  const C();
}
```

An initializer-list entry that reads a constructor parameter is allowed, and
initializer lists are not checked when the class declares several
constructors.

examples.bad:
class A {
  final a = const [];
  const A();
}

class B {
  final List<int> b;
  const B() : b = const [];
}

class C {
  final int x = 1, y = 2;
  const C();
}

// Initializer-list entry that ignores every parameter.
class D {
  final int value;
  final String label;
  const D(this.value) : label = 'fixed';
}

// A field initializer is flagged even when another constructor is not const.
class E {
  final String name = 'e';
  const E();
  E.other();
}

mixin class F {
  final int f = 0;
  const F();
}

examples.good:
// A getter instead of a field.
class A {
  List get a => const [];
  const A();
}

// Initializer-list entry that uses a constructor parameter.
class B {
  final int b;
  const B(int value) : b = value * 2;
}

// No const constructor: field initializers are fine.
class C {
  final c = const [];
  C();
}

// Static fields are not per-instance.
class D {
  static final d = <int>[];
  static const e = 1;
  const D();
}

// Several constructors: the initializer list is not checked.
class E {
  final int e;
  const E() : e = 0;
  const E.named(this.e);
}

// Implicit default constructor is never const.
class F {
  final f = 1;
}

// Field formal parameters, no initializers.
class G {
  final int x;
  final int y;
  const G(this.x, {this.y = 0});
}

// Parameter referenced in a nested expression.
class H {
  final int next;
  const H(int first) : next = (first + 1) * 2;
}

