docs:
Flags deprecations that are not carried through to related declarations.

Deprecating a class implies deprecating its constructors, and a deprecated
field implies that the initializing formal (`this.field`) that sets it is
deprecated too — and vice versa. Leaving one side unmarked means callers get
no warning on the path they actually use.

```dart
@deprecated
class A {
  A();                        // flagged: constructor not deprecated
}

class B {
  B({this.field});            // flagged: parameter not deprecated
  @Deprecated('Use x')
  Object? field;
}
```

Private fields are not checked. Deprecation metadata is resolved to
`dart:core`, including prefixed references and named `Deprecated`
constructors; user-defined lookalikes do not count.
Primary constructors are checked separately from their enclosing type;
only their own body metadata deprecates them. Header initializing formals
participate in the same field/parameter consistency checks.

examples.bad:
@deprecated
class A {
  A();
}

@Deprecated('Use B2 instead')
class B {
  B.named();

  @Deprecated('ok')
  B();
}

class C {
  C({this.field});

  @Deprecated('Use x instead')
  Object? field;
}

class D {
  D({@Deprecated('Use y instead') this.field});

  Object? field;
}

class E {
  E(this.value, {@deprecated this.legacy});

  final int value;
  final int? legacy;
}

@deprecated
enum Mode {
  on(1),
  off(0);

  const Mode(this.code);
  final int code;
}
@Deprecated.extend()
class Extendable {
  Extendable();
}

@Deprecated.implement()
class Implementable {
  Implementable();
}
@deprecated
extension type Representation(int value) {
  Representation.named(this.value);
}

@deprecated
extension type PrivateRepresentation._(int value) {}

typedef Dep = Deprecated;

@Dep('old')
class Aliased {
  Aliased();
}

@Dep.extend()
class AliasedNamed {
  AliasedNamed();
}

@deprecated
extension type const ConstRepresentation(int value) {}

@deprecated
extension type const ConstNamedRepresentation._(int value) {}

examples.good:
@deprecated
class A {
  @deprecated
  A();
}

@Deprecated('Use B2 instead')
class B {
  @Deprecated('Use B2.named instead')
  B.named();
}

class C {
  C({@Deprecated('Use x instead') this.field});

  @Deprecated('Use x instead')
  Object? field;
}

// Neither side deprecated.
class D {
  D(this.field);

  final Object? field;
}

// Private fields are not part of the public API.
class E {
  E(this._secret);

  @deprecated
  final int _secret;

  int get secret => _secret;
}

// A deprecated constructor in a non-deprecated class is fine.
class F {
  @Deprecated('Use F.create')
  F();

  F.create();
}

// Static fields are not initialized by formals.
class G {
  @deprecated
  static int counter = 0;

  G(int counter);
}

@Deprecated.extend()
class ConsistentNamed {
  @deprecated
  ConsistentNamed();
}

class ConsistentField {
  ConsistentField(@deprecated this.value);
  @Deprecated('old')
  final int value;
}

@Deprecated.new('old')
class ExplicitUnnamed {
  @Deprecated.new('old')
  ExplicitUnnamed();
}

// Representation fields have no reportable field-fragment name offset.
extension type DeprecatedRepresentationParameter(int value) {
  DeprecatedRepresentationParameter.named(@deprecated this.value);
}

typedef Dep = Deprecated;

@Dep('old')
class ConsistentAlias {
  @Dep('old')
  ConsistentAlias();
}

