Function topLevelCallback = const Callable();
set topLevelSetter(Function value) {}

class Receiver {
  Receiver(Function callback, {required Function named});
  Receiver.named({required Function callback});

  Function fieldCallback = const Callable();
  static Function staticCallback = const Callable();
  set callbackSetter(Function value) {}
  static set staticSetter(Function value) {}

  void instance(Function callback, {required Function named}) {}
  static void staticMethod(Function callback, {required Function named}) {}

  Function returnMethod() => const Callable();

  void assignments(Callable callback) {
    Function localCallback = callback;
    localCallback = callback;
    fieldCallback = callback;
    this.fieldCallback = callback;
    Receiver.staticCallback = callback;
    topLevelCallback = callback;
    callbackSetter = callback;
    this.callbackSetter = callback;
    Receiver.staticSetter = callback;
    topLevelSetter = callback;
  }

  void methodCalls(Callable callback, Receiver receiver) {
    accept(callback);
    acceptNamed(callback: callback);
    instance(callback, named: callback.call);
    instance(callback.call, named: callback);
    this.instance(callback, named: callback.call);
    receiver.instance(callback.call, named: callback);
    Receiver.staticMethod(callback, named: callback.call);
    Receiver.staticMethod(callback.call, named: callback);
  }

  void constructorCalls(Callable callback) {
    Receiver(callback, named: callback.call);
    Receiver(callback.call, named: callback);
    new Receiver(callback, named: callback.call);
    Receiver.named(callback: callback);
  }

  void localCalls(Callable callback) {
    void localFunction(Function value, {required Function named}) {}
    localFunction(callback, named: callback.call);
    localFunction(callback.call, named: callback);

    void Function(Function, {required Function named}) functionValue = localFunction;
    functionValue(callback, named: callback.call);

    final inferredFunctionValue = localFunction;
    inferredFunctionValue(callback, named: callback.call);
  }

  void scoped(List<Callable> callbacks) {
    Function localReturn() => const Callable();
    localReturn();
    for (Callable callback in callbacks) {
      accept(callback);
    }
    try {
      throw const Callable();
    } on Callable catch (callback) {
      accept(callback);
    }
