void outerCoercions(
  MutableCallable first,
  MutableCallable second,
  MutableCallable? nullable,
  bool condition,
) {
  void Function() conditional = condition ? first : second;
  void Function() cascade = first..value = 1;
  void Function() coalesced = nullable ?? second;
}

