// A local shadow declared in a try, catch or finally body is scoped to that
// body and must not suppress the call after the statement.
void scopedShadow() {
  try {
    void print(Object? value) {}
    print('shadowed');
  } catch (_) {
    void print(Object? value) {}
    print('shadowed');
  } finally {
